-- ~200 badges. Every rarity (22), every kind of plot (one badge each), streaks, luck, travel, estates, minigames,
-- and bigger tiers of the old ones — each with its own icon: an emoji, a rarity's plot art ('rarity:<id>') or a plot
-- kind's emoji ('kind:<id>'), drawn in a medal whose metal shows its tier (bronze → silver → gold → platinum →
-- diamond → prismatic).

alter table public.achievements drop constraint if exists achievements_category_check;
alter table public.achievements add constraint achievements_category_check
  check (category in ('creation', 'collection', 'exploration', 'mastery', 'community', 'rarity', 'daily', 'travel', 'estate', 'kinds'));
alter table public.achievements alter column key type text;
alter table public.achievements drop constraint if exists achievements_key_check;
alter table public.achievements add constraint achievements_key_check check (key ~ '^[a-z0-9_]{2,48}$');

create or replace function private.achievement_metrics(p_uid uuid) returns jsonb
language sql stable as $$
  select jsonb_build_object(
    'plots', (select count(*) from public.world_plots where owner_id = p_uid),
    'regions', (select count(distinct ((gx >> 13) * 8 + (gy >> 13))) from public.world_plots where owner_id = p_uid),
    'saved_tiles', (select coalesce(max(tile_count), 0) from public.artwork_versions where owner_id = p_uid and kind = 'save'),
    'publications', (select count(*) from public.artwork_publications where owner_id = p_uid and status in ('published', 'superseded')),
    'largest_publication', (select coalesce(max(plot_count), 0) from public.artwork_publications where owner_id = p_uid and status in ('published', 'superseded')),
    'max_colors', (select coalesce(max(color_count), 0) from public.artwork_publications where owner_id = p_uid and status in ('published', 'superseded')),
    'largest_group', (select coalesce(max(plot_count), 0) from public.canvas_groups where owner_id = p_uid and status = 'active'),
    'tracecraft', (select coalesce(max(highest_level), 0) from public.minigame_records where player_id = p_uid and game = 'tracecraft'),
    'colorburst', (select coalesce(max(highest_level), 0) from public.minigame_records where player_id = p_uid and game = 'colorburst'),
    'patternshift', (select coalesce(max(highest_level), 0) from public.minigame_records where player_id = p_uid and game = 'patternshift'),
    'paintpop', (select coalesce(max(highest_level), 0) from public.minigame_records where player_id = p_uid and game = 'paintpop'),
    'craft_best', (select coalesce(max(craft_score), 0) from public.artwork_publications where owner_id = p_uid and status in ('published', 'superseded')),
    'challenge_wins', (select count(*) from public.challenge_entries where owner_id = p_uid and place between 1 and 3),
    'rooms_visited', (select count(distinct host_id) from public.room_checkins where visitor_id = p_uid),
    'lightlines', (select coalesce(max(highest_level), 0) from public.minigame_records where player_id = p_uid and game = 'lightlines'),
    'minigame_wins', (select coalesce(sum(wins), 0) from public.minigame_records where player_id = p_uid),
    'appreciations_received', (select coalesce(sum(appreciation_count), 0) from public.artwork_publications where owner_id = p_uid),
    'appreciations_given', (select count(*) from public.gallery_reactions where player_id = p_uid),
    'upgrades', (select coalesce(sum(level - 1), 0) from public.world_plots where owner_id = p_uid),
    'rare_plots', (select count(*) from public.world_plots where owner_id = p_uid and rarity in ('epic', 'legendary', 'mythic')),
    'legendary_plots', (select count(*) from public.world_plots where owner_id = p_uid and rarity in ('legendary', 'mythic')),
    'mythic_plots', (select count(*) from public.world_plots where owner_id = p_uid and rarity = 'mythic'),
    'boosts', (select count(*) from public.boost_activations where player_id = p_uid))
  -- v1.3: ~200 badges
  || jsonb_build_object(
    'claims', (select count(*) from public.plot_ownership where player_id = p_uid),
    'rarities', (select count(distinct rarity) from public.world_plots where owner_id = p_uid),
    'shiny', (select count(*) from public.world_plots where owner_id = p_uid and shiny),
    'plot_types', (select count(distinct plot_type) from public.world_plots where owner_id = p_uid),
    'streak_best', (select coalesce(max(best), 0) from public.daily_streaks where player_id = p_uid),
    'checkin_days', (select coalesce(max(total_days), 0) from public.daily_streaks where player_id = p_uid),
    'sacrificed', (select coalesce(max(sacrificed), 0) from public.player_luck where player_id = p_uid),
    'lucky_rolls', (select coalesce(max(lucky_rolls), 0) from public.player_luck where player_id = p_uid),
    'stamps', (select count(*) from public.travel_visits where player_id = p_uid),
    'countries', (select count(distinct s.country) from public.travel_visits v join public.travel_stops s on s.id = v.stop_id where v.player_id = p_uid and s.country <> ''),
    'trips', (select count(*) from public.travel_trips where player_id = p_uid and mode in ('train', 'plane')),
    'pins', (select count(*) from public.travel_trips where player_id = p_uid and dest_lng is not null),
    'vehicle_bike', (select count(*) from public.vehicles_owned where player_id = p_uid and kind = 'bike'),
    'vehicle_car', (select count(*) from public.vehicles_owned where player_id = p_uid and kind = 'car'),
    'vehicle_jet', (select count(*) from public.vehicles_owned where player_id = p_uid and kind = 'jet'),
    'rent_days', (select count(*) from public.landlord_progress l join public.canvas_groups g on g.id = l.group_id where g.owner_id = p_uid and private.landlord_done(l.group_id, l.cycle)),
    'repairs', (select coalesce(sum(coalesce(array_length(l.repaired, 1), 0)), 0) from public.landlord_progress l join public.canvas_groups g on g.id = l.group_id where g.owner_id = p_uid),
    'tenants', (select coalesce(sum(l.requests), 0) from public.landlord_progress l join public.canvas_groups g on g.id = l.group_id where g.owner_id = p_uid),
    'ink_earned', (select coalesce(sum(delta), 0) from public.resource_ledger where player_id = p_uid and resource = 'ink' and delta > 0))
  || coalesce((select jsonb_object_agg('rar_' || rarity, n) from (select rarity, count(*) n from public.world_plots where owner_id = p_uid group by rarity) x), '{}'::jsonb)
  || coalesce((select jsonb_object_agg('kind_' || kind, n) from (select kind, count(*) n from public.canvas_groups where owner_id = p_uid and status = 'active' group by kind) x), '{}'::jsonb)
$$;

on conflict (key) do update set name = excluded.name, description = excluded.description, icon = excluded.icon, category = excluded.category,
  metric = excluded.metric, threshold = excluded.threshold, reward = excluded.reward, sort = excluded.sort;

-- one badge for every kind of plot
select 'kind_' || k.id, k.name, 'Own a ' || k.name || ' plot.', 'kind:' || k.id, 'kinds', 'kind_' || k.id, 1, '{"pigments": 10, "gallery_tokens": 1}'::jsonb, 600 + row_number() over (order by k.sort, k.id)
from public.plot_kinds k where k.enabled
on conflict (key) do update set name = excluded.name, description = excluded.description, icon = excluded.icon, category = excluded.category, metric = excluded.metric;
